<?php require_once __DIR__ . '/../includes/bootstrap.php'; require_role('admin');
if(request_method()==='POST'){require_csrf();$st=$pdo->prepare('INSERT INTO fees (student_id,invoice_no,amount,due_date,status) VALUES (:s,:i,:a,:d,\'pending\')');$st->execute(['s'=>(int)$_POST['student_id'],'i'=>'INV'.time(),'a'=>$_POST['amount'],'d'=>$_POST['due_date']]);}
$fees=$pdo->query('SELECT f.*,s.student_id FROM fees f JOIN students s ON s.id=f.student_id ORDER BY f.id DESC')->fetchAll(); $students=$pdo->query('SELECT id,student_id FROM students')->fetchAll(); include __DIR__ . '/../includes/header.php'; ?>
<section class="section"><div class="container"><div class="glass card"><h1>Fee Management & Invoices</h1><form method="post"><input type="hidden" name="_token" value="<?= csrf_token() ?>"><div class="card-grid"><select class="form-control" name="student_id"><?php foreach($students as $s):?><option value="<?= $s['id'] ?>"><?= e($s['student_id']) ?></option><?php endforeach;?></select><input class="form-control" name="amount" placeholder="Amount"><input class="form-control" type="date" name="due_date"></div><br><button class="btn">Create Invoice</button></form></div><div class="glass card" style="margin-top:1rem"><table class="table"><tr><th>Invoice</th><th>Student</th><th>Amount</th><th>Status</th><th>Payment</th></tr><?php foreach($fees as $f): ?><tr><td><?= e($f['invoice_no']) ?></td><td><?= e($f['student_id']) ?></td><td>₹<?= e($f['amount']) ?></td><td><?= e($f['status']) ?></td><td><a class="btn secondary" href="/public/pay.php?invoice=<?= e($f['invoice_no']) ?>">PayU Link</a></td></tr><?php endforeach; ?></table></div></div></section>
